create table if not exists public.ce_recovery_drills(id uuid primary key default gen_random_uuid(),status text not null check(status in('PLANNED','RUNNING','PASSED','FAILED')),rpo_minutes integer not null,rto_minutes integer not null,backup_verified boolean not null default false,restore_verified boolean not null default false,created_at timestamptz not null default now(),completed_at timestamptz);alter table public.ce_recovery_drills enable row level security;revoke all on public.ce_recovery_drills from public,anon,authenticated;grant select,insert,update,delete on public.ce_recovery_drills to service_role;